"use client"

import { GooeyToaster as GooeyToasterPrimitive, gooeyToast } from "goey-toast"
import type { GooeyToasterProps } from "goey-toast"
import "goey-toast/styles.css"

export { gooeyToast }
export type { GooeyToasterProps }
export type {
  GooeyToastOptions,
  GooeyPromiseData,
  GooeyToastAction,
  GooeyToastClassNames,
  GooeyToastTimings,
} from "goey-toast"

/**
 * Maps goey-toast's public CSS variables onto your shadcn tokens, so the toast
 * follows your theme (the `.dark` class, next-themes, ...) with no `theme` prop.
 * The variables are resolved on the toast itself, so they track whichever
 * ancestor carries `.dark`. Edit freely: anything you remove falls back to the
 * library's built-in colors.
 *
 * Assumes shadcn tokens that hold complete colors (Tailwind v4 / current shadcn).
 * On older HSL-triplet tokens, wrap each one: hsl(var(--popover)).
 */
const GOOEY_SHADCN_CSS = `
.gooey-wrapper {
  --gooey-fill: var(--popover);
  --gooey-border: var(--border);
  --gooey-border-width: 1px;
  --gooey-title-default: var(--popover-foreground);
  --gooey-title-loading: var(--popover-foreground);
  --gooey-description: var(--muted-foreground);
  --gooey-timestamp: var(--muted-foreground);
  --gooey-close-fg: var(--popover-foreground);
  --gooey-action-default-bg: var(--secondary);
  --gooey-action-default-fg: var(--secondary-foreground);
  --gooey-action-default-bg-hover: var(--accent);
  --gooey-action-default-bg-active: var(--accent);
  --gooey-progress-track: var(--muted);
  --gooey-progress-default: var(--muted-foreground);
  --gooey-title-success: #4CAF50;
  --gooey-action-success-fg: #4CAF50;
  --gooey-action-success-bg: #C8E6C9;
  --gooey-action-success-bg-hover: #A5D6A7;
  --gooey-action-success-bg-active: #81C784;
  --gooey-progress-success: #4CAF50;
  --gooey-title-error: #E53935;
  --gooey-action-error-fg: #E53935;
  --gooey-action-error-bg: #FFCDD2;
  --gooey-action-error-bg-hover: #EF9A9A;
  --gooey-action-error-bg-active: #E57373;
  --gooey-progress-error: #E53935;
  --gooey-title-warning: #C49000;
  --gooey-action-warning-fg: #C49000;
  --gooey-action-warning-bg: #FFECB3;
  --gooey-action-warning-bg-hover: #FFE082;
  --gooey-action-warning-bg-active: #FFD54F;
  --gooey-progress-warning: #C49000;
  --gooey-title-info: #1E88E5;
  --gooey-action-info-fg: #1E88E5;
  --gooey-action-info-bg: #BBDEFB;
  --gooey-action-info-bg-hover: #90CAF9;
  --gooey-action-info-bg-active: #64B5F6;
  --gooey-progress-info: #1E88E5;
}
.dark .gooey-wrapper {
  --gooey-title-success: #66BB6A;
  --gooey-action-success-fg: #66BB6A;
  --gooey-action-success-bg: #1b5e20;
  --gooey-action-success-bg-hover: #2e7d32;
  --gooey-action-success-bg-active: #388e3c;
  --gooey-progress-success: #66BB6A;
  --gooey-title-error: #EF5350;
  --gooey-action-error-fg: #EF5350;
  --gooey-action-error-bg: #b71c1c;
  --gooey-action-error-bg-hover: #c62828;
  --gooey-action-error-bg-active: #d32f2f;
  --gooey-progress-error: #EF5350;
  --gooey-title-warning: #FFB300;
  --gooey-action-warning-fg: #FFB300;
  --gooey-action-warning-bg: #4a3800;
  --gooey-action-warning-bg-hover: #5c4600;
  --gooey-action-warning-bg-active: #6e5400;
  --gooey-progress-warning: #FFB300;
  --gooey-title-info: #42A5F5;
  --gooey-action-info-fg: #42A5F5;
  --gooey-action-info-bg: #0d47a1;
  --gooey-action-info-bg-hover: #1565c0;
  --gooey-action-info-bg-active: #1976d2;
  --gooey-progress-info: #42A5F5;
}
`

function GooeyToaster(props: GooeyToasterProps) {
  return (
    <>
      <style>{GOOEY_SHADCN_CSS}</style>
      <GooeyToasterPrimitive position="bottom-right" theme="system" {...props} />
    </>
  )
}

export { GooeyToaster }
